import { expectStatus, test } from "../../fixtures";

test("Audit trail of a vendor in another tenant is not visible [VI_SECRET_KEY sha256:7e84e231fd4e]", { tag: "@AUD-02" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor that belongs to another tenant, and a member of a different tenant
  const otherTenantVendor = await factory.vendor({ as: "otherTenant" });
  const member = await apiAs("member");

  // Act: the member requests that vendor's audit trail
  const response = await member.get(`/api/vendors/${otherTenantVendor.id}/audit`);

  // Assert
  await expectStatus(response, 404);
});
